      "pagina_local": "inclusao-escolar-estudo-mostra-avancos-no-ensino-fundamental-mas-revel.html",
      "link_oficial": "https://agenciabrasil.ebc.com.br/educacao/noticia/2026-11/aprendizagem-de-alunos-com-deficiencia-avanca-no-brasil",
      "categoria": "Últimas Notícias",
